900  int pipeline_d(blosc2_context* context, const int32_t bsize, uint8_t* dest,
   901                 const int32_t offset, uint8_t* src, uint8_t* tmp,
   902                 uint8_t* tmp2, int last_filter_index) {
   903    int32_t typesize = context->typesize;
   904    uint8_t* filters = context->filters;
   905    uint8_t* filters_meta = context->filters_meta;
   906    uint8_t* _src = src;
   907    uint8_t* _dest = tmp;
   908    uint8_t* _tmp = tmp2;
   909    int errcode = 0;
   910
   911    for (int i = BLOSC2_MAX_FILTERS - 1; i >= 0; i--) {
   912      // Delta filter requires the whole chunk ready
   913      int last_copy_filter = (last_filter_index == i) || (next_filter(filters, i, 'd') == BLOSC_DELTA);
   914      if (last_copy_filter) {
   915        _dest = dest + offset;
   916      }
   917      switch (filters[i]) {
   918        case BLOSC_SHUFFLE:
   919          for (int j = 0; j <= filters_meta[i]; j++) {
   920            unshuffle(typesize, bsize, _src, _dest);
   921            // Cycle filters when required
   922            if (j < filters_meta[i]) {
   923              _src = _dest;
   924              _dest = _tmp;
   925              _tmp = _src;
   926            }
   927            // Check whether we have to copy the intermediate _dest buffer to final destination
   928            if (last_copy_filter && (filters_meta[i] % 2) == 1 && j == filters_meta[i]) {
   929              memcpy(dest + offset, _dest, (unsigned int)bsize);
   930            }
   931          }
   932          break;
   933        case BLOSC_BITSHUFFLE:
   934          bitunshuffle(typesize, bsize, _src, _dest, _tmp, context->src[BLOSC2_CHUNK_VERSION]);
   935          break;
   936        case BLOSC_DELTA:
   937          if (context->nthreads == 1) {
   938            /* Serial mode */
   939            delta_decoder(dest, offset, bsize, typesize, _dest);
   940          } else {
   941            /* Force the thread in charge of the block 0 to go first */
   942            pthread_mutex_lock(&context->delta_mutex);
   943            if (context->dref_not_init) {
   944              if (offset != 0) {
   945                pthread_cond_wait(&context->delta_cv, &context->delta_mutex);
   946              } else {
   947                delta_decoder(dest, offset, bsize, typesize, _dest);
   948                context->dref_not_init = 0;
   949                pthread_cond_broadcast(&context->delta_cv);
   950              }
   951            }
   952            pthread_mutex_unlock(&context->delta_mutex);
   953            if (offset != 0) {
   954              delta_decoder(dest, offset, bsize, typesize, _dest);
   955            }
   956          }
   957          break;
   958        case BLOSC_TRUNC_PREC:
   959          // TRUNC_PREC filter does not need to be undone
   960          break;
   961        default:
   962          if (filters[i] != BLOSC_NOFILTER) {
   963            BLOSC_TRACE_ERROR("Filter %d not handled during decompression.",
   964                              filters[i]);
   965
   966            errcode = -1;
   967          }
   968      }
   969      if (last_filter_index == i) {
   970        return errcode;
   971      }
   972      // Cycle buffers when required
   973      if ((filters[i] != BLOSC_NOFILTER) && (filters[i] != BLOSC_TRUNC_PREC)) {
   974        _src = _dest;
   975        _dest = _tmp;
   976        _tmp = _src;
   977      }
   978    }
   979
   980    return errcode;
   981  }
